parser.script:
// 芽果：device 匿名登录换 token，storage 缓存 5.5 小时（基准为 6h，留余量）。
var YG_LOGIN_URL = 'https://u.shytkjgs.com/user/v1/account/login';
var YG_DEVICE = '24250683a3bdb3f118dff25ba4b1cba1a';
var YG_TTL = 5.5 * 3600 * 1000;
function ygStrip(base) { return String(base || '').replace(/\/+$/, ''); }
function ygBody(raw) {
  // 形态归一：单条 meta 预取的处理器入参在旧引擎是打包数组 [响应体, 响应头]，
  // 新引擎逐参传递后首参即响应体。所有处理器都经 ygParse，在此一处归一。
  return (Array.isArray(raw) && raw.length > 0 && raw[0] && typeof raw[0] === 'object') ? raw[0] : raw;
}
function ygParse(raw) {
  raw = ygBody(raw);
  if (raw && typeof raw === 'object') return raw;
  if (typeof raw !== 'string' || !raw) return null;
  try { return JSON.parse(raw); } catch (e) { return null; }
}
async function ygToken(context) {
  var cached = null;
  try { cached = await context.storage.get('yg_token'); } catch (e) { cached = null; }
  if (cached) {
    try {
      var box = JSON.parse(cached);
      if (box && box.t && box.ts && (Date.now() - box.ts) < YG_TTL) return box.t;
    } catch (e) {}
  }
  var token = '';
  for (var attempt = 0; attempt < 2 && !token; attempt++) {
    try {
      var raw = await context.http.post(YG_LOGIN_URL, JSON.stringify({ device: YG_DEVICE }), { 'platform': '1', 'Content-Type': 'application/json' });
      var json = ygParse(raw);
      if (json && json.data) token = json.data.token || json.token || '';
    } catch (e) { token = ''; }
  }
  if (!token) throw new Error('芽果登录失败：未返回令牌');
  try { await context.storage.set('yg_token', JSON.stringify({ t: token, ts: Date.now() })); } catch (e) {}
  return token;
}
async function ygHeaders(context) {
  var token = await ygToken(context);
  return { 'authorization': token, 'platform': '1', 'version_name': '3.8.3.1' };
}
function ygDrama(node) {
  var t = (node && node.theater) || node || {};
  var id = t.id || t.theater_id || t.theater_parent_id;
  if (!id) return null;
  var tags = t.tags || [];
  return {
    id: String(id),
    title: t.title || t.name || '',
    cover: t.cover_url || t.son_cover_url || t.cover || '',
    description: t.descrip || t.introduction || t.desc || '',
    episodeCount: t.total || t.total_num || t.current_num || '',
    tags: Array.isArray(tags) ? tags : []
  };
}
async function ygCatalog(context) {
  var headers = await ygHeaders(context);
  var cls = String((context && context.category) || '1');
  var page = Number((context && context.page) || 1);
  var url;
  if (cls === '9') {
    url = ygStrip(context.baseUrl) + '/cloud/v1/first_level_ranking/detail?id=1';
  } else {
    if (cls !== '1' && !/^\d+$/.test(cls)) cls = '1';
    url = ygStrip(context.baseUrl) + '/cloud/v2/theater/home_page?theater_class_id=' + encodeURIComponent(cls) + '&type=1&class2_ids=0&page_num=' + page + '&page_size=24';
  }
  return {
    __meta: true,
    __fetchUrl: url,
    __fetchHeaders: headers,
    __fetchResponseType: 'json',
    __processor: 'ygPickList'
  };
}
function ygRows(json) {
  if (!json) return [];
  var data = json.data || {};
  if (Array.isArray(data.list)) return data.list;
  if (data.theater && Array.isArray(data.theater.search_data)) return data.theater.search_data;
  return [];
}
function ygPickList(raw) {
  var rows = ygRows(ygParse(raw));
  var out = [];
  for (var i = 0; i < rows.length; i++) {
    var item = ygDrama(rows[i]);
    if (item) out.push(item);
  }
  return out;
}
function parseList(raw, context) { return ygCatalog(context); }
function parseCategory(raw, context) { return ygCatalog(context); }
async function parseSearch(raw, context) {
  var headers = await ygHeaders(context);
  var query = (context && context.keyword) || '';
  return {
    __meta: true,
    __fetchUrl: ygStrip(context.baseUrl) + '/v3/search',
    __fetchMethod: 'post',
    __fetchBody: JSON.stringify({ text: query }),
    __fetchHeaders: (function(){ var h = {}; for (var k in headers) { h[k] = headers[k]; } h['Content-Type'] = 'application/json'; return h; })(),
    __fetchResponseType: 'json',
    __processor: 'ygPickList'
  };
}
async function ygDetailMeta(context, processor) {
  var headers = await ygHeaders(context);
  var id = (context && context.id) || '';
  return {
    __meta: true,
    __fetchUrl: ygStrip(context.baseUrl) + '/v2/theater_parent/detail?theater_parent_id=' + encodeURIComponent(String(id)),
    __fetchHeaders: headers,
    __fetchResponseType: 'json',
    __processor: processor
  };
}
function parseDetail(raw, context) { return ygDetailMeta(context, 'ygPickDetail'); }
function ygPickDetail(raw) {
  var json = ygParse(raw);
  var data = (json && json.data) || {};
  var total = Number(data.total) || ((data.theaters || []).length) || '';
  var item = {
    id: String((context && context.id) || data.theater_parent_id || data.id || ''),
    title: data.title || data.share_title || '',
    cover: data.cover_url || data.share_cover || '',
    description: data.descrip || data.introduction || '',
    episodeCount: total,
    status: Number(data.is_over) === 2 ? 'finished' : ''
  };
  return item;
}
function parseEpisodes(raw, context) { return ygDetailMeta(context, 'ygPickEpisodes'); }
function ygPickEpisodes(raw) {
  var json = ygParse(raw);
  var data = (json && json.data) || {};
  var id = data.theater_parent_id || data.id || '';
  var rows = data.theaters || [];
  var out = [];
  for (var i = 0; i < rows.length; i++) {
    var node = rows[i];
    var video = node.son_video_url || node.video_url || '';
    if (!video) continue;
    var number = Number(node.num || node.sort) || (i + 1);
    out.push({
      id: String(node.id || number),
      title: node.son_title || node.title || ('第' + number + '集'),
      number: number,
      url: '/v2/theater_parent/detail?theater_parent_id=' + encodeURIComponent(String(id)) + '#ep=' + encodeURIComponent(String(number))
    });
  }
  return out;
}
var YG_EP = '';
function ygFindPlay(json, epKey) {
  if (!json || !json.data) return '';
  var rows = json.data.theaters || [];
  for (var i = 0; i < rows.length; i++) {
    var node = rows[i];
    var number = String(Number(node.num || node.sort) || (i + 1));
    if (number === String(epKey) || String(node.id) === String(epKey)) {
      return node.son_video_url || node.video_url || '';
    }
  }
  return '';
}
function ygPickVideo(raw) { return ygFindPlay(ygParse(raw), YG_EP); }
async function parseVideo(raw, context) {
  var url = (context && context.url) || '';
  var cut = url.indexOf('#ep=');
  YG_EP = cut >= 0 ? decodeURIComponent(url.slice(cut + 4)) : '';
  var hit = ygFindPlay(ygParse(raw), YG_EP);
  if (hit) return hit;
  var target = cut >= 0 ? url.slice(0, cut) : url;
  // 路由级预取不带脚本现取的令牌（sourceAuthHeader 只有声明式登录），常态拿到
  // data=null 的空壳，二次请求才是带权取流；选集 url 是相对路径，先补全再判断。
  if (target.indexOf('http') !== 0 && target.indexOf('/') === 0) {
    target = ygStrip((context && context.baseUrl) || '') + target;
  }
  if (target.indexOf('http') === 0) {
    var headers = await ygHeaders(context);
    return {
      __meta: true,
      __fetchUrl: target,
      __fetchHeaders: headers,
      __fetchResponseType: 'json',
      __processor: 'ygPickVideo'
    };
  }
  return '';
}
